import subprocess, re, difflib

def get(path):
    out = subprocess.check_output(['objdump','-d',path,'--no-show-raw-insn'], text=True, stderr=subprocess.DEVNULL)
    insns=[]
    for l in out.splitlines():
        m = re.match(r'\s+([0-9a-f]+):\s+(.*)$', l)
        if m:
            insns.append((int(m.group(1),16), m.group(2).strip()))
    return insns

def norm(t):
    t = re.sub(r'<[^>]*>','',t)
    t = re.sub(r'\s+',' ',t).strip()
    return t

# normalize but KEEP immediate constants small (they may matter), replace only large addrs
def normkeep(t):
    t = re.sub(r'<[^>]*>','',t)
    # replace hex that look like code addresses (>=0x400000) with H
    def rep(m):
        v=int(m.group(0),16)
        return 'H' if v>=0x400000 else m.group(0)
    t = re.sub(r'0x[0-9a-f]+', rep, t)
    t = re.sub(r'\s+',' ',t).strip()
    return t

v = [ (a,normkeep(t)) for a,t in get('/out-vul/dotnet_fuzzer') if 0x41a900<=a<0x41d600 ]
f = [ (a,normkeep(t)) for a,t in get('/out-fix/dotnet_fuzzer') if 0x41a800<=a<0x41d600 ]
# also normalize branch targets (they shift): replace "jXX 41...." operand with "jXX T"
def normbranch(s):
    return re.sub(r'\b(j\w+|call)\s+[0-9a-f]{6}\b', r'\1 T', s)
vs=[normbranch(t) for a,t in v]
fs=[normbranch(t) for a,t in f]
sm=difflib.SequenceMatcher(a=vs,b=fs,autojunk=False)
print("ratio",round(sm.ratio(),4))
n=0
for tag,i1,i2,j1,j2 in sm.get_opcodes():
    if tag!='equal':
        # skip pure nop/padding differences
        n+=1
        print(f"\n### {tag} vuladdr={hex(v[i1][0])}.. fixaddr={hex(f[j1][0])}.. (v {i2-i1} insns, f {j2-j1} insns)")
        for x in vs[i1:i2][:14]: print("  V:",x)
