import subprocess, re
def get(path):
    out=subprocess.check_output(['objdump','-d',path,'--no-show-raw-insn'],stderr=subprocess.DEVNULL).decode()
    insns=[]
    for l in out.splitlines():
        m=re.match(r'\s+([0-9a-f]+):\s+(.*)$',l)
        if m: insns.append((int(m.group(1),16),m.group(2).strip()))
    return insns
def norm(t):
    t=re.sub(r'<[^>]*>','',t)
    t=re.sub(r'\s+',' ',t).strip()
    return t
v=[norm(t) for a,t in get('/out-vul/dotnet_fuzzer')]
f=[norm(t) for a,t in get('/out-fix/dotnet_fuzzer')]
# normalize branch targets and addresses
def nb(s):
    s=re.sub(r'\b(j\w+|call)\s+[0-9a-f]{5,}\b',r'\1 T',s)
    s=re.sub(r'0x[0-9a-f]{5,}','H',s)
    return s
vs=[nb(x) for x in v]; fs=[nb(x) for x in f]
import difflib
sm=difflib.SequenceMatcher(a=vs,b=fs,autojunk=False)
print("WHOLE .text similarity:",round(sm.ratio(),5))
n=0
for tag,i1,i2,j1,j2 in sm.get_opcodes():
    if tag!='equal':
        n+=1
        # show only non-trivial (not pure address/nop) hunks
        vfrag=vs[i1:i2]; ffrag=fs[j1:j2]
        def istry(frag):
            return all(x.startswith('nop') or x.startswith('xchg') or re.match(r'^(j\w+|call) T$',x) for x in frag)
        if not (istry(vfrag) and istry(ffrag)):
            print(f"{tag} v[{i1}:{i2}] f[{j1}:{j2}]")
            for x in vfrag[:5]: print("  V:",x)
            for x in ffrag[:5]: print("  F:",x)
print("total diff hunks:",n)
